/*! flashcards-15.js — Vokabel-Checklisten der Phasen 1–4 plus die vier kleinen Restbuckets
 * (bewerbung/, foundations/, plans/, templates/) — Flashcard-Pass 3.
 * Harvested per AUTHORING §6.1. 161 table rows → 150 cards: one row was a mis-parsed
 * Deklinationstabelle (Nom.|die|das|die), ten were containment-flagged near-duplicates.
 */
window.FLASHCARDS = (window.FLASHCARDS || []).concat([
  /* ---- Phase 1 · Grundlagen ---- */
  { id:"fc9401", de:"Lesezugriff", article:"der", plural:"die Lesezugriffe", en:"read access", vi:"quyền đọc", ex:"Für das Log brauchst du nur Lesezugriff, nicht mehr.", exEn:"For the log you only need read access, nothing more.", ipa:"LEE-ze-tsuu-grif", coll:"Lesezugriff bekommen / gewähren", tip:"Kopf: der Zugriff → der. Gegenstück: der Schreibzugriff. Beide von *zugreifen auf* + Akkusativ.", topic:"Linux", level:"B1" },
  { id:"fc9402", de:"Hauptsatz", article:"der", plural:"die Hauptsätze", en:"main clause", vi:"mệnh đề chính", ex:"Im Hauptsatz steht das Verb immer an Position zwei.", exEn:"In a main clause the verb is always in position two.", ipa:"HAUPT-zats", coll:"im Hauptsatz stehen", tip:"Umlaut im Plural. Die wichtigste Regel des Deutschen hängt an diesem Wort: Verb an Position 2.", topic:"Grammar", level:"B1" },
  { id:"fc9403", de:"Nebensatz", article:"der", plural:"die Nebensätze", en:"subordinate clause", vi:"mệnh đề phụ", ex:"Im Nebensatz rutscht das Verb ans Ende — *…, weil der Test fehlschlägt.*", exEn:"In a subordinate clause the verb slides to the end.", ipa:"NEE-ben-zats", coll:"einen Nebensatz einleiten", tip:"Umlaut im Plural. Verb ans Ende — der zweite Grundpfeiler nach der Position-2-Regel.", topic:"Grammar", level:"B1" },
  { id:"fc9404", de:"Fall", article:"der", plural:"die Fälle", en:"grammatical case", vi:"cách (ngữ pháp)", ex:"Nach *mit* steht immer der dritte Fall, also Dativ.", exEn:"After „mit“ it's always the third case, i.e. dative.", ipa:"FAL", coll:"der dritte Fall", tip:"Umlaut im Plural. Deutsche nennen die Fälle oft nach Nummer: erster Fall = Nominativ, dritter = Dativ.", topic:"Grammar", level:"B1" },
  { id:"fc9405", de:"Folge", article:"die", plural:"die Folgen", en:"episode", vi:"tập (podcast)", ex:"Ich höre jede Woche eine Folge auf dem Weg zur Arbeit.", exEn:"I listen to one episode a week on the way to work.", ipa:"FOL-ge", coll:"eine Folge hören", tip:"-e → die. Zweite Bedeutung: *die Folgen* = consequences. Der Kontext trennt sie zuverlässig.", topic:"Reading", level:"B1" },
  { id:"fc9406", de:"Untertitel", article:"der", plural:"die Untertitel", en:"subtitle", vi:"phụ đề", ex:"Schalte die Untertitel erst beim zweiten Hören dazu.", exEn:"Only turn the subtitles on for the second listen.", ipa:"UN-ter-tii-tel", coll:"Untertitel einschalten", tip:"Kopf: der Titel → der, Plural = Singular. Deutsche Untertitel zu deutschem Ton bringen mehr als englische.", topic:"Reading", level:"B1" },
  { id:"fc9407", de:"Sendung", article:"die", plural:"die Sendungen", en:"broadcast, show", vi:"chương trình", ex:"Die Sendung läuft täglich um acht und dauert eine Viertelstunde.", exEn:"The show runs daily at eight and lasts a quarter of an hour.", ipa:"ZEN-dung", coll:"eine Sendung verfolgen", tip:"-ung → die. Von *senden*. Zweite Bedeutung: die Postsendung (a parcel).", topic:"Reading", level:"B1" },
  { id:"fc9408", de:"verstehen", article:"—", plural:"—", en:"to understand", vi:"hiểu", ex:"Beim ersten Hören verstehe ich vielleicht die Hälfte — das reicht.", exEn:"On the first listen I understand maybe half — that's enough.", ipa:"fer-SHTEE-en", coll:"etwas falsch verstehen", tip:"Stark und untrennbar: versteht, verstand, verstanden — kein *ge-*. *sich verstehen mit* = to get on with someone.", topic:"Foundations", level:"B1" },
  { id:"fc9409", de:"Ziel", article:"das", plural:"die Ziele", en:"goal, objective", vi:"mục tiêu", ex:"Das Ziel dieser Phase ist nicht Perfektion, sondern Verständlichkeit.", exEn:"The goal of this phase isn't perfection but being understood.", ipa:"TSEEL", coll:"ein Ziel erreichen / setzen", tip:"Auch: der Bahnhof als Ziel einer Reise. *zielen auf* = to aim at.", topic:"Foundations", level:"B1" },
  { id:"fc9410", de:"Wortschatz", article:"der", plural:"die Wortschätze", en:"vocabulary", vi:"vốn từ", ex:"Der passive Wortschatz wächst schneller als der aktive — das ist normal.", exEn:"Passive vocabulary grows faster than active — that's normal.", ipa:"VORT-shats", coll:"den Wortschatz aufbauen", tip:"Wörtlich „Wortschatz“ = treasure of words. Umlaut im Plural, aber der Plural ist selten.", topic:"Foundations", level:"B1" },
  { id:"fc9411", de:"Woche", article:"die", plural:"die Wochen", en:"week", vi:"tuần", ex:"Diese Woche nehme ich mir zwei Kapitel vor, nicht fünf.", exEn:"This week I'm taking on two chapters, not five.", ipa:"VO-khe", coll:"diese / nächste Woche", tip:"-e → die. Ohne Präposition im Akkusativ: *diese Woche*, *letzten Montag* — Zeitangaben stehen im Akkusativ.", topic:"Alltag", level:"B1" },
  { id:"fc9412", de:"Alltag", article:"der", plural:"—", en:"daily routine, everyday life", vi:"thường nhật", ex:"Deutsch muss in den Alltag, sonst bleibt es Schulwissen.", exEn:"German has to get into daily life, otherwise it stays school knowledge.", ipa:"AL-taak", coll:"in den Alltag einbauen", tip:"Kein Plural. Adjektiv: alltäglich = everyday, banal. *im Alltag* (Dativ) vs *in den Alltag* (Richtung, Akkusativ).", topic:"Alltag", level:"B1" },
  { id:"fc9413", de:"Wochenende", article:"das", plural:"die Wochenenden", en:"weekend", vi:"cuối tuần", ex:"Am Wochenende lese ich, unter der Woche höre ich nur.", exEn:"At the weekend I read, during the week I only listen.", ipa:"VO-khen-en-de", coll:"am Wochenende", tip:"*am* Wochenende, aber *unter der* Woche. Kopf: das Ende → das.", topic:"Alltag", level:"B1" },
  { id:"fc9414", de:"planen", article:"—", plural:"—", en:"to plan", vi:"lên kế hoạch", ex:"Plane lieber vier feste Termine als sieben gute Vorsätze.", exEn:"Better to plan four fixed slots than seven good intentions.", ipa:"PLAA-nen", coll:"eine Woche planen", tip:"Schwach: plant, plante, geplant. Trennbare Verwandte: einplanen (allocate), verplanen (book up).", topic:"Foundations", level:"B1" },
  { id:"fc9415", de:"Umgebungsvariable", article:"die", plural:"die Umgebungsvariablen", en:"environment variable", vi:"biến môi trường", ex:"Das Passwort gehört in eine Umgebungsvariable, nicht in den Code.", exEn:"The password belongs in an environment variable, not in the code.", ipa:"UM-gee-bungs-va-ri-aa-ble", coll:"eine Umgebungsvariable setzen", tip:"Kopf: die Variable → die. Fugen-s: Umgebungsvariable. Im Team oft kurz *die Env-Variable*.", topic:"Linux", level:"B2" },
  { id:"fc9416", de:"Anleitung", article:"die", plural:"die Anleitungen", en:"guide, instructions", vi:"hướng dẫn", ex:"Die Anleitung im Wiki ist zwei Versionen alt — ich aktualisiere sie.", exEn:"The guide in the wiki is two versions old — I'll update it.", ipa:"AN-lay-tung", coll:"einer Anleitung folgen", tip:"-ung → die. Verb: anleiten. *die Bedienungsanleitung* ist das Handbuch zum Gerät.", topic:"Reading", level:"B1" },
  { id:"fc9417", de:"Überschrift", article:"die", plural:"die Überschriften", en:"heading, title", vi:"tiêu đề", ex:"Lies erst alle Überschriften, dann entscheide, was du wirklich brauchst.", exEn:"Read all the headings first, then decide what you actually need.", ipa:"ÜÜ-ber-shrift", coll:"eine Überschrift überfliegen", tip:"Kopf: die Schrift → die. Die Technik dazu heißt *überfliegen* (to skim) — Pflicht bei Fachtexten.", topic:"Reading", level:"B1" },
  { id:"fc9418", de:"Unternehmen", article:"das", plural:"die Unternehmen", en:"company", vi:"doanh nghiệp", ex:"Das Unternehmen hat rund zweitausend Mitarbeitende an vier Standorten.", exEn:"The company has around two thousand employees at four locations.", ipa:"un-ter-NEE-men", coll:"ein mittelständisches Unternehmen", tip:"Plural = Singular. Formeller als *die Firma*. Verb *unternehmen* = to undertake, mit anderem Sinn.", topic:"Workplace", level:"B1" },
  { id:"fc9419", de:"Pause", article:"die", plural:"die Pausen", en:"pause, break", vi:"giờ nghỉ", ex:"Eine Pause im Satz ist kein Fehler — sie gibt dir Zeit zum Denken.", exEn:"A pause mid-sentence isn't a mistake — it buys you thinking time.", ipa:"PAU-ze", coll:"eine Pause machen", tip:"-e → die. Im Gespräch bewusst eingesetzt wirkt die Pause souverän, nicht unsicher.", topic:"Speaking", level:"B1" },
  { id:"fc9420", de:"Vorstellung", article:"die", plural:"die Vorstellungen", en:"introduction; idea", vi:"giới thiệu; hình dung", ex:"Nach der kurzen Vorstellung steigen wir direkt ins Thema ein.", exEn:"After the short introduction we'll go straight into the topic.", ipa:"FOR-shte-lung", coll:"eine kurze Vorstellung", tip:"-ung → die. Drei Bedeutungen: Vorstellung im Team, *Gehaltsvorstellung* (expectation) und *keine Vorstellung haben* (no idea).", topic:"Speaking", level:"B1" },
  { id:"fc9421", de:"Entwickler", article:"der", plural:"die Entwickler", en:"developer", vi:"lập trình viên", ex:"Als Entwickler arbeite ich vor allem im Backend.", exEn:"As a developer I mainly work on the backend.", ipa:"ent-VIK-ler", coll:"als Entwickler arbeiten", tip:"Plural = Singular. Weiblich: die Entwicklerin. Im Beruf steht kein Artikel: *Ich bin Entwickler.*", topic:"Workplace", level:"B1" },
  { id:"fc9422", de:"Team", article:"das", plural:"die Teams", en:"team", vi:"nhóm", ex:"Unser Team besteht aus sechs Personen und einer Teamleiterin.", exEn:"Our team consists of six people and a team lead.", ipa:"TIIM", coll:"im Team arbeiten", tip:"*das*, englisch ausgesprochen. Deutsch *die Mannschaft* gilt eher dem Sport.", topic:"Workplace", level:"B1" },
  { id:"fc9423", de:"Meldung", article:"die", plural:"die Meldungen", en:"message, notification", vi:"thông báo", ex:"Welche Meldung steht genau im Log?", exEn:"What exactly does the message in the log say?", ipa:"MEL-dung", coll:"eine Meldung auslösen", tip:"-ung → die. Verb: melden. Enger Verwandter: die Fehlermeldung (error message).", topic:"Software Development", level:"B1" },
  { id:"fc9424", de:"Rechner", article:"der", plural:"die Rechner", en:"computer, machine", vi:"máy tính", ex:"Auf meinem Rechner läuft der Test durch, auf dem Server nicht.", exEn:"On my machine the test passes, on the server it doesn't.", ipa:"REKH-ner", coll:"auf dem Rechner laufen", tip:"Plural = Singular. Von *rechnen*. Etwas altmodisch neben *der Computer*, aber in Doku und Prüfung Standard.", topic:"Software Development", level:"B1" },
  { id:"fc9425", de:"Ordner", article:"der", plural:"die Ordner", en:"folder, directory", vi:"thư mục", ex:"Leg die Konfiguration in denselben Ordner wie das Skript.", exEn:"Put the config in the same folder as the script.", ipa:"ORD-ner", coll:"einen Ordner anlegen", tip:"Plural = Singular. Auch *das Verzeichnis* (directory) — das steht häufiger in Linux-Doku.", topic:"Linux", level:"B1" },
  { id:"fc9426", de:"Benutzeroberfläche", article:"die", plural:"die Benutzeroberflächen", en:"user interface", vi:"giao diện người dùng", ex:"Die Benutzeroberfläche ist neu, die Logik dahinter unverändert.", exEn:"The user interface is new, the logic behind it unchanged.", ipa:"be-NUT-tser-oo-ber-fle-khe", coll:"die Benutzeroberfläche gestalten", tip:"Kopf: die Fläche → die. Im Team sagt man meist *das UI* oder *das Frontend*.", topic:"Software Development", level:"B2" },
  { id:"fc9427", de:"Betriebssystem", article:"das", plural:"die Betriebssysteme", en:"operating system", vi:"hệ điều hành", ex:"Welches Betriebssystem läuft auf den Build-Rechnern?", exEn:"Which operating system runs on the build machines?", ipa:"be-TREEPS-züs-teem", coll:"ein Betriebssystem aufsetzen", tip:"Kopf: das System → das. Fugen-s: Betriebssystem. Abkürzung im Deutschen genauso: das OS.", topic:"Linux", level:"B1" },
  { id:"fc9428", de:"Gruß", article:"der", plural:"die Grüße", en:"greeting, sign-off", vi:"lời chào", ex:"Als Gruß reicht in der Firma fast immer *Viele Grüße*.", exEn:"As a sign-off, „Viele Grüße“ is nearly always enough at work.", ipa:"GRUUS", coll:"Viele Grüße / Mit freundlichen Grüßen", tip:"ß im Singular, Umlaut plus ß im Plural: Grüße. *Mit freundlichen Grüßen* ist förmlich, *Viele Grüße* der Alltag.", topic:"Writing", level:"B1" },
  { id:"fc9429", de:"besprechen", article:"—", plural:"—", en:"to discuss", vi:"trao đổi, bàn bạc", ex:"Das besprechen wir kurz im Daily, nicht per Mail.", exEn:"We'll discuss that briefly in the daily, not by email.", ipa:"be-SHPRE-khen", coll:"etwas kurz besprechen", tip:"Stark und untrennbar: bespricht, besprach, besprochen — kein *ge-*. Nomen: die Besprechung (meeting).", topic:"Speaking", level:"B1" },

  /* ---- Phase 2 · telc B2, Diskussion und Meeting ---- */
  { id:"fc9430", de:"Anforderungsprofil", article:"das", plural:"die Anforderungsprofile", en:"job requirements profile", vi:"yêu cầu tuyển dụng", ex:"Das Anforderungsprofil nennt Kubernetes — davon steht im Vertrag nichts.", exEn:"The requirements profile names Kubernetes — the contract says nothing about it.", ipa:"AN-for-de-rungs-pro-feel", coll:"dem Anforderungsprofil entsprechen", tip:"Kopf: das Profil → das. Fugen-s. In Stellenanzeigen die Überschrift über *Ihr Profil*.", topic:"Career", level:"C1" },
  { id:"fc9431", de:"Verhandlungsposition", article:"die", plural:"die Verhandlungspositionen", en:"bargaining position", vi:"vị thế đàm phán", ex:"Ein zweites Angebot verbessert deine Verhandlungsposition deutlich.", exEn:"A second offer improves your bargaining position considerably.", ipa:"fer-HAND-lungs-po-zi-tsyoon", coll:"die Verhandlungsposition stärken", tip:"Kopf: die Position → die, wie alle Nomen auf *-ion*.", topic:"Career", level:"C1" },
  { id:"fc9432", de:"Weiterbildung", article:"die", plural:"die Weiterbildungen", en:"further training", vi:"đào tạo nâng cao", ex:"Fünf Tage Weiterbildung im Jahr sind bei uns tariflich geregelt.", exEn:"Five days of further training a year are set by collective agreement here.", ipa:"VAY-ter-bil-dung", coll:"eine Weiterbildung beantragen", tip:"-ung → die. In Deutschland ein starkes Verhandlungsargument — oft leichter zu bekommen als Gehalt.", topic:"Career", level:"B2" },
  { id:"fc9433", de:"aufweichen", article:"—", plural:"—", en:"to water down", vi:"làm loãng, nới lỏng", ex:"Wenn wir die Definition of Done aufweichen, ist sie wertlos.", exEn:"If we water down the definition of done, it's worthless.", ipa:"AUF-vay-khen", coll:"eine Regel aufweichen", tip:"Trennbar: weiche … auf. Wörtlich: Brot in Wasser aufweichen. Im Meeting immer negativ gemeint.", topic:"Workplace", level:"C1" },
  { id:"fc9434", de:"unverhältnismäßig", article:"—", plural:"—", en:"disproportionate", vi:"không tương xứng", ex:"Der Aufwand steht unverhältnismäßig zum Nutzen.", exEn:"The effort is disproportionate to the benefit.", ipa:"UN-fer-helt-nis-me-sikh", coll:"unverhältnismäßig hoch", tip:"*un-* + *Verhältnis* + *-mäßig*. Ein Wort, das in Diskussionen sachlich wirkt, wo *zu viel* wertend klingt.", topic:"Speaking", level:"C1" },
  { id:"fc9435", de:"bemerken", article:"—", plural:"—", en:"to notice; to remark", vi:"nhận ra; nhận xét", ex:"Ich habe bemerkt, dass der Fehler nur freitags auftritt.", exEn:"I've noticed the error only occurs on Fridays.", ipa:"be-MER-ken", coll:"nebenbei bemerken", tip:"Untrennbar, kein *ge-*: bemerkt. Nomen: die Bemerkung (remark). Nicht *merken* (to memorise, *sich merken*).", topic:"Speaking", level:"B2" },
  { id:"fc9436", de:"Passiv", article:"das", plural:"—", en:"passive voice", vi:"thể bị động", ex:"Im Protokoll steht fast alles im Passiv: *Es wurde beschlossen …*", exEn:"In minutes nearly everything is in the passive: „it was decided …“", ipa:"PAS-eef", coll:"etwas ins Passiv setzen", tip:"Kein Plural. Die zwei Sorten heißen Vorgangspassiv (*wird gemacht*) und Zustandspassiv (*ist gemacht*).", topic:"Grammar", level:"B2" },
  { id:"fc9437", de:"Einstiegshürde", article:"die", plural:"die Einstiegshürden", en:"barrier to entry", vi:"rào cản gia nhập", ex:"Die Einstiegshürde ist das Setup, nicht die Sprache selbst.", exEn:"The barrier to entry is the setup, not the language itself.", ipa:"AYN-shteeks-hür-de", coll:"die Einstiegshürde senken", tip:"Kopf: die Hürde → die. Fugen-s. Bild aus der Leichtathletik — man *senkt* oder *nimmt* eine Hürde.", topic:"Workplace", level:"C1" },
  { id:"fc9438", de:"Alarmierung", article:"die", plural:"die Alarmierungen", en:"alerting", vi:"cảnh báo", ex:"Die Alarmierung greift erst ab fünf Prozent Fehlerrate.", exEn:"Alerting only kicks in from a five percent error rate.", ipa:"a-lar-MEE-rung", coll:"die Alarmierung einrichten", tip:"-ung → die; von *alarmieren*, daher *-ierung*. Im Team meist *das Alerting*.", topic:"DevOps", level:"C1" },
  { id:"fc9439", de:"Betrieb", article:"der", plural:"die Betriebe", en:"operation; company", vi:"vận hành; doanh nghiệp", ex:"Im laufenden Betrieb tauschen wir die Datenbank nicht aus.", exEn:"We don't swap the database out during live operation.", ipa:"be-TREEP", coll:"im laufenden Betrieb", tip:"Zwei Bedeutungen: der Betrieb als Firma und der Betrieb als Lauf eines Systems. *in Betrieb* = running.", topic:"DevOps", level:"B2" },
  { id:"fc9440", de:"Speicherung", article:"die", plural:"die Speicherungen", en:"storage (the act of storing)", vi:"việc lưu trữ", ex:"Die Speicherung personenbezogener Daten braucht eine Rechtsgrundlage.", exEn:"Storing personal data requires a legal basis.", ipa:"SHPAY-khe-rung", coll:"die Speicherung von Daten", tip:"-ung → die. *die Speicherung* ist der Vorgang, *der Speicher* der Ort — die Endung macht den Unterschied.", topic:"Database", level:"C1" },
  { id:"fc9441", de:"verhindert", article:"—", plural:"—", en:"unable to attend, prevented", vi:"bận, không tham dự được", ex:"Ich bin am Donnerstag leider verhindert — kann jemand das Protokoll übernehmen?", exEn:"Unfortunately I can't make it on Thursday — can someone take the minutes?", ipa:"fer-HIN-dert", coll:"leider verhindert sein", tip:"Falscher Freund: *verhindert sein* heißt nicht „behindert“, sondern schlicht „ich kann nicht“ — die höflichste Absage im Kalender.", topic:"Workplace", level:"B2" },
  { id:"fc9442", de:"Nachrichten", article:"die", plural:"die Nachrichten (nur Plural)", en:"the news", vi:"tin tức", ex:"Die Nachrichten um acht sind langsam gesprochen und gut zum Üben.", exEn:"The eight o'clock news is spoken slowly and good for practice.", ipa:"NAAKH-rikh-ten", coll:"die Nachrichten hören", tip:"In dieser Bedeutung nur Plural. Der Singular *die Nachricht* ist eine einzelne Nachricht.", topic:"Reading", level:"B1" },
  { id:"fc9443", de:"Meinung", article:"die", plural:"die Meinungen", en:"opinion", vi:"ý kiến", ex:"Meiner Meinung nach lohnt sich der Umbau erst im nächsten Quartal.", exEn:"In my opinion the rebuild only pays off next quarter.", ipa:"MAY-nung", coll:"meiner Meinung nach", tip:"-ung → die. *meiner Meinung nach* mit Dativ und nachgestelltem *nach* — die häufigste B2-Formel überhaupt.", topic:"Speaking", level:"B1" },
  { id:"fc9444", de:"Fähigkeit", article:"die", plural:"die Fähigkeiten", en:"ability, skill", vi:"năng lực", ex:"Die Fähigkeit, ein Problem klar zu beschreiben, zählt mehr als jedes Framework.", exEn:"The ability to describe a problem clearly counts more than any framework.", ipa:"FEE-ikh-kayt", coll:"eine Fähigkeit mitbringen", tip:"-keit → die, immer. Von *fähig*. Im Lebenslauf heißen sie *die Kenntnisse* oder *die Kompetenzen*.", topic:"Career", level:"B2" },
  { id:"fc9445", de:"Bevormundung", article:"die", plural:"die Bevormundungen", en:"patronising, paternalism", vi:"sự áp đặt", ex:"Feste Regeln sind keine Bevormundung, wenn das Team sie selbst gesetzt hat.", exEn:"Fixed rules aren't patronising if the team set them itself.", ipa:"be-FOR-mun-dung", coll:"als Bevormundung empfinden", tip:"-ung → die. Von *der Vormund* (legal guardian). Ein starkes Wort — in Diskussionen ein echter Vorwurf.", topic:"Speaking", level:"C1" },
  { id:"fc9446", de:"handlungsfähig", article:"—", plural:"—", en:"able to act", vi:"có thể xử lý", ex:"Wir brauchen genug Rechte, um im Incident handlungsfähig zu bleiben.", exEn:"We need enough permissions to stay able to act during an incident.", ipa:"HAND-lungs-fee-ikh", coll:"handlungsfähig bleiben", tip:"*-fähig* an ein Nomen gehängt heißt „kann das“: handlungsfähig, lieferfähig, zahlungsfähig.", topic:"Workplace", level:"C1" },
  { id:"fc9447", de:"These", article:"die", plural:"die Thesen", en:"thesis, claim", vi:"luận điểm", ex:"Meine These ist, dass der Cache das Problem nur verschiebt.", exEn:"My claim is that the cache only postpones the problem.", ipa:"TEE-ze", coll:"eine These aufstellen", tip:"-e → die, Plural *-n*. Nicht *die Hypothese* (im Incident) — die These vertritt man, die Hypothese prüft man.", topic:"Speaking", level:"C1" },
  { id:"fc9448", de:"Ansicht", article:"die", plural:"die Ansichten", en:"view, opinion", vi:"quan điểm", ex:"Ich bin der Ansicht, dass wir zuerst messen und dann optimieren sollten.", exEn:"I'm of the view that we should measure first and optimise second.", ipa:"AN-zikht", coll:"der Ansicht sein, dass …", tip:"Kopf: die Sicht → die. *der Ansicht sein* steht im Genitiv-losen Dativ — eine feste Wendung, formeller als *ich finde*.", topic:"Speaking", level:"B2" },
  { id:"fc9449", de:"Zeitverschwendung", article:"die", plural:"—", en:"waste of time", vi:"lãng phí thời gian", ex:"Ein Meeting ohne Agenda ist für acht Leute Zeitverschwendung.", exEn:"A meeting without an agenda is a waste of time for eight people.", ipa:"TSAYT-fer-shven-dung", coll:"reine Zeitverschwendung", tip:"-ung → die, praktisch ohne Plural. Von *verschwenden* (to waste).", topic:"Workplace", level:"B2" },
  { id:"fc9450", de:"Pendelzeit", article:"die", plural:"die Pendelzeiten", en:"commuting time", vi:"thời gian đi lại", ex:"Zwei Bürotage sparen mir vier Stunden Pendelzeit pro Woche.", exEn:"Two office days save me four hours of commuting a week.", ipa:"PEN-del-tsayt", coll:"Pendelzeit sparen", tip:"Kopf: die Zeit → die. Von *pendeln* (to commute); die Person heißt *der Pendler*.", topic:"Alltag", level:"B2" },
  { id:"fc9451", de:"einigen (sich auf)", article:"—", plural:"—", en:"to agree on", vi:"thống nhất", ex:"Können wir uns auf zwei feste Bürotage einigen?", exEn:"Can we agree on two fixed office days?", ipa:"AY-ni-gen", coll:"sich auf einen Kompromiss einigen", tip:"Reflexiv, *auf* + Akkusativ. Nomen: die Einigung. Stärker als *zustimmen* — beide Seiten bewegen sich.", topic:"Speaking", level:"B2" },
  { id:"fc9452", de:"Diskussion", article:"die", plural:"die Diskussionen", en:"discussion", vi:"cuộc thảo luận", ex:"Die Diskussion dreht sich im Kreis — lass uns abstimmen.", exEn:"The discussion is going round in circles — let's put it to a vote.", ipa:"dis-ku-SYOON", coll:"eine Diskussion führen", tip:"-ion → die, endbetont. *sich im Kreis drehen* ist die Standardformel für eine festgefahrene Runde.", topic:"Speaking", level:"B1" },
  { id:"fc9453", de:"Vorschlag", article:"der", plural:"die Vorschläge", en:"proposal, suggestion", vi:"đề xuất", ex:"Mein Vorschlag wäre, das in zwei Schritten zu machen.", exEn:"My suggestion would be to do it in two steps.", ipa:"FOR-shlaak", coll:"einen Vorschlag machen", tip:"Umlaut im Plural. *Mein Vorschlag wäre* im Konjunktiv II klingt deutlich weicher als *Ich schlage vor*.", topic:"Speaking", level:"B1" },
  { id:"fc9454", de:"Erfahrung", article:"die", plural:"die Erfahrungen", en:"experience", vi:"kinh nghiệm", ex:"Nach meiner Erfahrung scheitert so eine Migration nie an der Technik.", exEn:"In my experience a migration like that never fails on the technology.", ipa:"er-FAA-rung", coll:"Erfahrung sammeln", tip:"-ung → die. *Erfahrung machen* = to have an experience; *Erfahrung haben* = to be experienced.", topic:"Career", level:"B1" },
  { id:"fc9455", de:"Standpunkt", article:"der", plural:"die Standpunkte", en:"standpoint, position", vi:"lập trường", ex:"Aus Sicherheitssicht bleibe ich bei meinem Standpunkt.", exEn:"From a security standpoint I'm sticking to my position.", ipa:"SHTANT-punkt", coll:"bei seinem Standpunkt bleiben", tip:"Kopf: der Punkt → der. Fester als *die Meinung* — man verlässt einen Standpunkt nicht leichtfertig.", topic:"Speaking", level:"B2" },
  { id:"fc9456", de:"Komplexität", article:"die", plural:"die Komplexitäten", en:"complexity", vi:"độ phức tạp", ex:"Wir verschieben die Komplexität nur, wir entfernen sie nicht.", exEn:"We're only moving the complexity, we're not removing it.", ipa:"kom-plek-si-TEET", coll:"Komplexität reduzieren", tip:"-tät → die, immer, endbetont. Wie: die Qualität, die Priorität, die Kapazität.", topic:"Architecture", level:"B2" },
  { id:"fc9457", de:"Risiko", article:"das", plural:"die Risiken", en:"risk", vi:"rủi ro", ex:"Das größte Risiko ist nicht der Ausfall, sondern der stille Datenverlust.", exEn:"The biggest risk isn't downtime but silent data loss.", ipa:"RII-zi-ko", coll:"ein Risiko eingehen", tip:"Unregelmäßiger Plural: *die Risiken*, nicht *Risikos*. Wie das Thema → die Themen.", topic:"Architecture", level:"B2" },
  { id:"fc9458", de:"leiden", article:"—", plural:"—", en:"to suffer", vi:"chịu thiệt", ex:"Unter dem engen Zeitplan leidet vor allem die Testabdeckung.", exEn:"It's mainly test coverage that suffers under the tight schedule.", ipa:"LAY-den", coll:"unter etwas leiden", tip:"Stark: leidet, litt, gelitten. *unter* + Dativ. Nicht *leiten* (to lead) — ein Buchstabe, ganz anderes Wort.", topic:"Speaking", level:"B2" },
  { id:"fc9459", de:"Einladung", article:"die", plural:"die Einladungen", en:"invitation", vi:"lời mời", ex:"In der Einladung stehen Agenda und Ziel — sonst sage ich ab.", exEn:"The invitation states the agenda and the goal — otherwise I decline.", ipa:"AYN-laa-dung", coll:"eine Einladung annehmen / absagen", tip:"-ung → die. Verb: einladen (lädt ein, lud ein, eingeladen) — stark und trennbar.", topic:"Writing", level:"B1" },
  { id:"fc9460", de:"Beitrag", article:"der", plural:"die Beiträge", en:"contribution; post", vi:"phần đóng góp; bài đăng", ex:"Danke für deinen Beitrag — den nehme ich ins Protokoll auf.", exEn:"Thanks for your contribution — I'll put it in the minutes.", ipa:"BAY-traak", coll:"einen Beitrag leisten", tip:"Umlaut im Plural. Auch: der Versicherungsbeitrag (premium) und der Beitrag im Forum.", topic:"Writing", level:"B2" },
  { id:"fc9461", de:"Aufzeichnung", article:"die", plural:"die Aufzeichnungen", en:"recording", vi:"bản ghi", ex:"Die Aufzeichnung liegt im Wiki, falls jemand nicht dabei sein konnte.", exEn:"The recording is in the wiki in case anyone couldn't attend.", ipa:"AUF-tsaykh-nung", coll:"eine Aufzeichnung bereitstellen", tip:"-ung → die. Von *aufzeichnen*. Plural *die Aufzeichnungen* heißt auch: handschriftliche Notizen.", topic:"Writing", level:"B2" },
  { id:"fc9462", de:"beisteuern", article:"—", plural:"—", en:"to contribute", vi:"góp vào", ex:"Zu dem Punkt kann ich nichts beisteuern, da kennt sich Aylin besser aus.", exEn:"I can't contribute anything on that point, Aylin knows it better.", ipa:"BAY-shtoy-ern", coll:"etwas zur Diskussion beisteuern", tip:"Trennbar: steuere … bei. *zu* + Dativ. Bescheidener als *sagen* — man legt etwas dazu.", topic:"Speaking", level:"C1" },
  { id:"fc9463", de:"überarbeiten", article:"—", plural:"—", en:"to revise", vi:"chỉnh sửa lại", ex:"Ich überarbeite den Abschnitt und schicke ihn morgen erneut.", exEn:"I'll revise the section and send it again tomorrow.", ipa:"üü-ber-AR-bay-ten", coll:"einen Entwurf überarbeiten", tip:"Untrennbar, kein *ge-*: überarbeitet. Reflexiv *sich überarbeiten* heißt dagegen: zu viel arbeiten.", topic:"Writing", level:"B2" },
  { id:"fc9464", de:"Empfänger", article:"der", plural:"die Empfänger", en:"recipient", vi:"người nhận", ex:"Setz die Betroffenen ins To-Feld, alle anderen als Empfänger in Kopie.", exEn:"Put those affected in the To field, everyone else as recipients in copy.", ipa:"emp-FENG-er", coll:"den Empfänger eintragen", tip:"Plural = Singular. Von *empfangen*. Gegenstück: der Absender.", topic:"Writing", level:"B1" },
  { id:"fc9465", de:"Absender", article:"der", plural:"die Absender", en:"sender", vi:"người gửi", ex:"Prüf den Absender genau, bevor du auf den Link klickst.", exEn:"Check the sender carefully before clicking the link.", ipa:"AP-zen-der", coll:"den Absender prüfen", tip:"Plural = Singular. Von *absenden*. Im Phishing-Training das Schlüsselwort.", topic:"Writing", level:"B1" },

  /* ---- Phase 3 · Architektur, Fachtexte, Hörverstehen ---- */
  { id:"fc9466", de:"Bewertung", article:"die", plural:"die Bewertungen", en:"assessment, rating", vi:"đánh giá", ex:"Die Bewertung im Selbsttest sagt dir, welches Modul du wiederholen solltest.", exEn:"The self-test assessment tells you which module to redo.", ipa:"be-VER-tung", coll:"eine Bewertung abgeben", tip:"-ung → die. Von *bewerten*. Sachlicher Nachbar: die Beurteilung.", topic:"Exam", level:"B2" },
  { id:"fc9467", de:"Schwäche", article:"die", plural:"die Schwächen", en:"weakness", vi:"điểm yếu", ex:"Meine größte Schwäche im Hören sind Zahlen, nicht Fachwörter.", exEn:"My biggest weakness in listening is numbers, not technical terms.", ipa:"SHVE-khe", coll:"eine Schwäche eingestehen", tip:"-e → die. Von *schwach*, mit Umlaut. Gegenteil: die Stärke. Beide kommen im Vorstellungsgespräch garantiert.", topic:"Exam", level:"B2" },
  { id:"fc9468", de:"Schwelle", article:"die", plural:"die Schwellen", en:"threshold", vi:"ngưỡng", ex:"Ab welcher Schwelle soll der Alarm auslösen?", exEn:"From what threshold should the alert fire?", ipa:"SHVEL-e", coll:"eine Schwelle überschreiten", tip:"-e → die. Wörtlich die Türschwelle. Fachlich auch *der Schwellenwert* (threshold value).", topic:"DevOps", level:"B2" },
  { id:"fc9469", de:"Systemausfall", article:"der", plural:"die Systemausfälle", en:"system outage", vi:"sự cố hệ thống", ex:"Beim Systemausfall im März waren wir vier Stunden offline.", exEn:"During the system outage in March we were offline for four hours.", ipa:"züs-TEEM-aus-fal", coll:"einen Systemausfall verursachen", tip:"Kopf: der Ausfall → der, Umlaut im Plural. Von *ausfallen* — das gilt auch für Menschen: *Er fällt krank aus.*", topic:"DevOps", level:"B2" },
  { id:"fc9470", de:"Konnektor", article:"der", plural:"die Konnektoren", en:"connector, conjunction", vi:"từ nối", ex:"Der Konnektor *obwohl* leitet einen Nebensatz ein, *trotzdem* nicht.", exEn:"The connector „obwohl“ introduces a subordinate clause, „trotzdem“ doesn't.", ipa:"ko-nek-TOOR", coll:"einen Konnektor verwenden", tip:"-or → der, Plural *-oren* mit Betonungswechsel: kon-nek-TOR → Kon-nek-TOO-ren.", topic:"Grammar", level:"C1" },
  { id:"fc9471", de:"Neustart", article:"der", plural:"die Neustarts", en:"restart", vi:"khởi động lại", ex:"Nach dem Neustart war der Speicher wieder frei — die Ursache aber nicht behoben.", exEn:"After the restart the memory was free again — but the cause wasn't fixed.", ipa:"NOY-shtart", coll:"einen Neustart durchführen", tip:"Kopf: der Start → der. Verb: neu starten (getrennt) oder *neustarten*. Umgangssprachlich: rebooten.", topic:"Linux", level:"B1" },
  { id:"fc9472", de:"Entlastung", article:"die", plural:"die Entlastungen", en:"relief, offloading", vi:"giảm tải", ex:"Der Cache dient der Entlastung der Datenbank, nicht der Geschwindigkeit.", exEn:"The cache serves to offload the database, not to gain speed.", ipa:"ent-LAS-tung", coll:"zur Entlastung beitragen", tip:"-ung → die. Gilt für Systeme wie für Menschen — *Entlastung* im Team heißt: Aufgaben abgeben.", topic:"Architecture", level:"C1" },
  { id:"fc9473", de:"Diskursmarker", article:"der", plural:"die Diskursmarker", en:"discourse marker", vi:"từ đệm diễn ngôn", ex:"Diskursmarker wie *also*, *na ja* und *sagen wir mal* geben dir Zeit zum Denken.", exEn:"Discourse markers like „also“ and „na ja“ buy you thinking time.", ipa:"dis-KURS-mar-ker", coll:"Diskursmarker einstreuen", tip:"Plural = Singular. Nicht Füllwörter, sondern Struktursignale — sie lassen dich flüssiger klingen, als du bist.", topic:"Speaking", level:"C1" },
  { id:"fc9474", de:"Invalidierung", article:"die", plural:"die Invalidierungen", en:"invalidation", vi:"vô hiệu hoá", ex:"Die Invalidierung des Caches ist schwerer als das Befüllen.", exEn:"Cache invalidation is harder than filling the cache.", ipa:"in-va-li-DEE-rung", coll:"die Invalidierung auslösen", tip:"-ung → die, von *invalidieren*. Gegenteil des vertrauten *die Validierung*.", topic:"Architecture", level:"C1" },
  { id:"fc9475", de:"Backoffice", article:"das", plural:"—", en:"back office", vi:"hệ thống quản trị nội bộ", ex:"Im Backoffice sehen die Kolleginnen die Bestellung mit allen Zwischenständen.", exEn:"In the back office colleagues see the order with every intermediate state.", ipa:"BEK-o-fis", coll:"im Backoffice sichtbar", tip:"*das*, wie *das Büro*. Meint hier die interne Verwaltungsoberfläche, nicht die Abteilung.", topic:"Software Development", level:"B2" },
  { id:"fc9476", de:"Millisekunde", article:"die", plural:"die Millisekunden", en:"millisecond", vi:"mili giây", ex:"Wir liegen bei achtzig Millisekunden im Mittel, im 99. Perzentil bei vierhundert.", exEn:"We're at eighty milliseconds on average, four hundred at the 99th percentile.", ipa:"MI-li-ze-kun-de", coll:"in Millisekunden messen", tip:"-e → die, wie die Sekunde. Abkürzung *ms* wird *em-es* gesprochen.", topic:"DevOps", level:"B1" },
  { id:"fc9477", de:"Region", article:"die", plural:"die Regionen", en:"region", vi:"vùng", ex:"Die Daten liegen in einer europäischen Region, das ist vertraglich zugesichert.", exEn:"The data sits in a European region, that's contractually guaranteed.", ipa:"re-GYOON", coll:"in einer Region betreiben", tip:"-ion → die, endbetont. In der Cloud der Standardbegriff — *die Verfügbarkeitszone* ist die Ebene darunter.", topic:"Cloud", level:"B2" },
  { id:"fc9478", de:"bestreiten", article:"—", plural:"—", en:"to dispute, to deny", vi:"phủ nhận", ex:"Dass wir ein Problem haben, bestreitet niemand — nur die Ursache ist strittig.", exEn:"Nobody disputes that we have a problem — only the cause is contested.", ipa:"be-SHTRAY-ten", coll:"eine Behauptung bestreiten", tip:"Stark und untrennbar: bestreitet, bestritt, bestritten. Zweite Bedeutung: die Kosten bestreiten (to cover).", topic:"Speaking", level:"C1" },
  { id:"fc9479", de:"sich auskennen (mit)", article:"—", plural:"—", en:"to know one's way around", vi:"rành về", ex:"Mit Kubernetes kenne ich mich aus, mit Terraform weniger.", exEn:"I know my way around Kubernetes, less so Terraform.", ipa:"zikh AUS-ke-nen", coll:"sich mit etwas auskennen", tip:"Reflexiv und trennbar: kenne mich … aus. *mit* + Dativ. Bescheidener und natürlicher als *Ich bin Experte*.", topic:"Speaking", level:"B2" },
  { id:"fc9480", de:"Umstieg", article:"der", plural:"die Umstiege", en:"switch, migration", vi:"sự chuyển đổi", ex:"Der Umstieg auf die neue Version dauert schätzungsweise zwei Sprints.", exEn:"The switch to the new version will take an estimated two sprints.", ipa:"UM-shteek", coll:"der Umstieg auf etwas", tip:"*auf* + Akkusativ. Von *umsteigen* — dasselbe Wort benutzt man beim Zug wechseln.", topic:"Architecture", level:"B2" },
  { id:"fc9481", de:"Praxis", article:"die", plural:"die Praxen", en:"practice, the real world", vi:"thực tế", ex:"In der Praxis sieht das Deployment selten so sauber aus wie im Diagramm.", exEn:"In practice the deployment rarely looks as clean as in the diagram.", ipa:"PRAK-sis", coll:"in der Praxis", tip:"Der Plural *die Praxen* meint Arztpraxen; für „Praxis“ als Erfahrung gibt es keinen Plural. Adjektiv: praktisch.", topic:"Foundations", level:"B2" },
  { id:"fc9482", de:"Gehörtraining", article:"das", plural:"—", en:"ear training", vi:"luyện nghe", ex:"Zwanzig Minuten Gehörtraining täglich bringen mehr als drei Stunden am Sonntag.", exEn:"Twenty minutes of ear training a day beats three hours on Sunday.", ipa:"ge-HÖÖR-trey-ning", coll:"Gehörtraining machen", tip:"Kopf: das Training → das. Von *das Gehör* (hearing) — nicht von *gehören* (to belong).", topic:"Foundations", level:"B2" },
  { id:"fc9483", de:"Fachsprache", article:"die", plural:"die Fachsprachen", en:"technical language, jargon", vi:"ngôn ngữ chuyên ngành", ex:"Die Fachsprache ist das kleinere Problem — die Alltagssätze drumherum sind schwerer.", exEn:"Technical language is the smaller problem — the everyday sentences around it are harder.", ipa:"FAKH-shpraa-khe", coll:"die Fachsprache beherrschen", tip:"Kopf: die Sprache → die. *Fach-* als Präfix ist überall: der Fachbegriff, die Fachabteilung, der Fachkräftemangel.", topic:"Foundations", level:"B2" },
  { id:"fc9484", de:"Datenfluss", article:"der", plural:"die Datenflüsse", en:"data flow", vi:"luồng dữ liệu", ex:"Zeichne den Datenfluss auf, dann wird die Abhängigkeit sofort sichtbar.", exEn:"Draw the data flow and the dependency becomes visible at once.", ipa:"DAA-ten-flus", coll:"den Datenfluss aufzeichnen", tip:"Umlaut und Doppel-s im Plural: *Flüsse*. Kopf: der Fluss → der — auch der Fluss in der Landschaft.", topic:"Architecture", level:"B2" },
  { id:"fc9485", de:"Architektur", article:"die", plural:"die Architekturen", en:"architecture", vi:"kiến trúc", ex:"Die Architektur ist die Summe der Entscheidungen, die schwer zu ändern sind.", exEn:"Architecture is the sum of the decisions that are hard to change.", ipa:"ar-khi-tek-TUUR", coll:"die Architektur entwerfen", tip:"-ur → die, endbetont. Das *ch* klingt wie *k*: ar-chi-tek-TUR.", topic:"Architecture", level:"B2" },
  { id:"fc9486", de:"Fachbegriff", article:"der", plural:"die Fachbegriffe", en:"technical term", vi:"thuật ngữ", ex:"Erklär den Fachbegriff einmal kurz, dann benutz ihn ohne Entschuldigung weiter.", exEn:"Explain the technical term once, then keep using it without apologising.", ipa:"FAKH-be-grif", coll:"einen Fachbegriff einführen", tip:"Kopf: der Begriff → der. Von *begreifen* (to grasp) — ein Begriff ist wörtlich das Gegriffene.", topic:"Foundations", level:"B2" },
  { id:"fc9487", de:"Wochenziel", article:"das", plural:"die Wochenziele", en:"weekly goal", vi:"mục tiêu tuần", ex:"Ein Wochenziel, nicht fünf — sonst erreichst du keines davon.", exEn:"One weekly goal, not five — otherwise you'll reach none of them.", ipa:"VO-khen-tseel", coll:"ein Wochenziel setzen", tip:"Kopf: das Ziel → das. Fugen-n: Wochenziel, wie Wochenende und Wochenplan.", topic:"Foundations", level:"B1" },
  { id:"fc9488", de:"Arbeitsspeicher", article:"der", plural:"—", en:"RAM, main memory", vi:"bộ nhớ trong", ex:"Der Dienst braucht zwei Gigabyte Arbeitsspeicher, mehr nicht.", exEn:"The service needs two gigabytes of RAM, no more.", ipa:"AR-bayts-shpay-kher", coll:"Arbeitsspeicher belegen", tip:"Kopf: der Speicher → der. Fugen-s. Gegenstück: der Festplattenspeicher.", topic:"Linux", level:"B2" },
  { id:"fc9489", de:"umgehen", article:"—", plural:"—", en:"to bypass; to handle", vi:"vòng qua; xử lý", ex:"Die Prüfung lässt sich über den zweiten Endpoint umgehen — das ist die Lücke.", exEn:"The check can be bypassed via the second endpoint — that's the hole.", ipa:"um-GEE-en", coll:"eine Prüfung umgehen", tip:"Zwei Verben, ein Wort: untrennbar *umGEHen* = to bypass; trennbar *UMgehen mit* = to deal with. Die Betonung entscheidet.", topic:"Security", level:"C1" },
  { id:"fc9490", de:"abraten (von)", article:"—", plural:"—", en:"to advise against", vi:"khuyên không nên", ex:"Von einem Umbau kurz vor dem Release rate ich klar ab.", exEn:"I'd clearly advise against a rebuild just before the release.", ipa:"AP-raa-ten", coll:"von etwas abraten", tip:"Trennbar und stark: rate … ab, riet … ab, abgeraten. *von* + Dativ. Gegenteil: zu etwas raten.", topic:"Speaking", level:"C1" },
  { id:"fc9491", de:"Dokumentation", article:"die", plural:"die Dokumentationen", en:"documentation", vi:"tài liệu", ex:"Die Dokumentation entsteht beim Bauen, nicht danach.", exEn:"Documentation happens while building, not afterwards.", ipa:"do-ku-men-ta-TSYOON", coll:"die Dokumentation pflegen", tip:"-tion → die, endbetont. Kurzform im Team: *die Doku*.", topic:"Software Development", level:"B1" },
  { id:"fc9492", de:"Kopfnomen", article:"das", plural:"die Kopfnomen", en:"head noun", vi:"danh từ chính", ex:"Das Kopfnomen steht im Deutschen immer hinten — es bestimmt den Artikel.", exEn:"In German the head noun always comes last — it determines the article.", ipa:"KOPF-noo-men", coll:"das Kopfnomen bestimmen", tip:"Der wichtigste Trick für Komposita: *die Datenbank* ist *die*, weil *die Bank* hinten steht.", topic:"Grammar", level:"C1" },
  { id:"fc9493", de:"Absatz", article:"der", plural:"die Absätze", en:"paragraph", vi:"đoạn văn", ex:"Ein Absatz, ein Gedanke — dann liest es sich auch auf Deutsch flüssig.", exEn:"One paragraph, one thought — then it reads fluently in German too.", ipa:"AP-zats", coll:"einen Absatz einfügen", tip:"Umlaut im Plural. Auch: der Absatz am Schuh und der Absatz im Vertrieb (sales).", topic:"Writing", level:"B2" },
  { id:"fc9494", de:"erschließen", article:"—", plural:"—", en:"to work out, to infer", vi:"suy luận nghĩa", ex:"Unbekannte Wörter erschließt du aus dem Kontext, nicht aus dem Wörterbuch.", exEn:"You infer unknown words from context, not from the dictionary.", ipa:"er-SHLEE-sen", coll:"aus dem Kontext erschließen", tip:"Stark und untrennbar: erschließt, erschloss, erschlossen. Die zentrale Lesetechnik für Fachtexte.", topic:"Reading", level:"C1" },
  { id:"fc9495", de:"Gültigkeitsdauer", article:"die", plural:"die Gültigkeitsdauern", en:"validity period, TTL", vi:"thời hạn hiệu lực", ex:"Die Gültigkeitsdauer des Tokens liegt bei fünfzehn Minuten.", exEn:"The token's validity period is fifteen minutes.", ipa:"GÜL-tikh-kayts-dau-er", coll:"die Gültigkeitsdauer setzen", tip:"Kopf: die Dauer → die. Von *gültig*. Im Team meist einfach *die TTL*.", topic:"Security", level:"C1" },
  { id:"fc9496", de:"Skizze", article:"die", plural:"die Skizzen", en:"sketch", vi:"bản phác", ex:"Ich mache eine Skizze an das Whiteboard, dann reden wir über dasselbe Bild.", exEn:"I'll do a sketch on the whiteboard, then we're talking about the same picture.", ipa:"SKIT-se", coll:"eine Skizze machen", tip:"-e → die. Verb: skizzieren. Beim Architekturgespräch die schnellste Art, Missverständnisse zu beenden.", topic:"Architecture", level:"B2" },
  { id:"fc9497", de:"weiterleiten", article:"—", plural:"—", en:"to forward", vi:"chuyển tiếp", ex:"Die Anfrage leite ich an das Platform-Team weiter.", exEn:"I'll forward the request to the platform team.", ipa:"VAY-ter-lay-ten", coll:"eine Anfrage weiterleiten", tip:"Trennbar: leite … weiter. *an* + Akkusativ. Gilt für Mails wie für Netzwerkverkehr.", topic:"Networking", level:"B1" },
  { id:"fc9498", de:"ablegen", article:"—", plural:"—", en:"to store, to file", vi:"lưu vào", ex:"Wo legen wir das Ergebnis ab — im Cache oder direkt in der Datenbank?", exEn:"Where do we store the result — in the cache or straight in the database?", ipa:"AP-lee-gen", coll:"Daten ablegen", tip:"Trennbar: lege … ab. Auch: eine Prüfung ablegen (to sit an exam) — dieselbe Form, anderer Sinn.", topic:"Database", level:"B2" },
  { id:"fc9499", de:"Pfeil", article:"der", plural:"die Pfeile", en:"arrow", vi:"mũi tên", ex:"Der Pfeil zeigt, wer wen aufruft — nicht, wo die Daten liegen.", exEn:"The arrow shows who calls whom — not where the data lives.", ipa:"PFAYL", coll:"ein Pfeil zeigt auf …", tip:"Das *pf* am Wortanfang wird wirklich als beides gesprochen: p+f. Wie Pfanne, Pflicht, Pfad.", topic:"Architecture", level:"B1" },
  { id:"fc9500", de:"Sicherheitsfilter", article:"der", plural:"die Sicherheitsfilter", en:"security filter", vi:"bộ lọc bảo mật", ex:"Der Sicherheitsfilter greift vor dem Controller, nicht danach.", exEn:"The security filter runs before the controller, not after.", ipa:"ZIKH-er-hayts-fil-ter", coll:"den Sicherheitsfilter durchlaufen", tip:"Kopf: der Filter → der, Plural = Singular. Fugen-s: Sicherheitsfilter.", topic:"Security", level:"B2" },
  { id:"fc9501", de:"Reproduktion", article:"die", plural:"die Reproduktionen", en:"reproduction (of a bug)", vi:"tái hiện lỗi", ex:"Ohne verlässliche Reproduktion suchen wir im Dunkeln.", exEn:"Without a reliable reproduction we're searching in the dark.", ipa:"re-pro-duk-TSYOON", coll:"eine Reproduktion beschreiben", tip:"-tion → die, endbetont. Im Ticket heißen die Schritte dazu *die Schritte zur Reproduktion*.", topic:"Debugging", level:"C1" },
  { id:"fc9502", de:"nachvollziehen", article:"—", plural:"—", en:"to trace, to follow, to understand", vi:"lần theo, hiểu được", ex:"Ich kann nachvollziehen, warum ihr euch so entschieden habt.", exEn:"I can understand why you decided that way.", ipa:"NAAKH-fol-tsee-en", coll:"etwas nachvollziehen können", tip:"Trennbar am *nach-*: vollziehe … nach. Zwei Register: technisch einen Ablauf verfolgen, menschlich eine Entscheidung verstehen.", topic:"Speaking", level:"C1" },
  { id:"fc9503", de:"Verhalten", article:"das", plural:"—", en:"behaviour", vi:"hành vi", ex:"Ein Refactoring ändert die Struktur, nicht das Verhalten.", exEn:"A refactoring changes the structure, not the behaviour.", ipa:"fer-HAL-ten", coll:"das Verhalten ändern", tip:"Substantivierter Infinitiv, deshalb *das* und kein Plural. Gilt für Code wie für Menschen.", topic:"Software Development", level:"B2" },
  { id:"fc9504", de:"Entscheidung", article:"die", plural:"die Entscheidungen", en:"decision", vi:"quyết định", ex:"Die Entscheidung gehört ins Protokoll, sonst wird sie in vier Wochen neu diskutiert.", exEn:"The decision belongs in the minutes, otherwise it gets rediscussed in four weeks.", ipa:"ent-SHAY-dung", coll:"eine Entscheidung dokumentieren", tip:"-ung → die. Verb: entscheiden (entscheidet, entschied, entschieden). Als Architekturdokument: der Entscheidungsdatensatz (ADR).", topic:"Architecture", level:"B2" },

  /* ---- Phase 4 · Meetings, Protokoll, Präsentation ---- */
  { id:"fc9505", de:"Kann-Beschreibung", article:"die", plural:"die Kann-Beschreibungen", en:"can-do statement", vi:"mô tả năng lực", ex:"Die Kann-Beschreibung für B2 verlangt, dass du spontan an einer Fachdiskussion teilnimmst.", exEn:"The B2 can-do statement requires you to join a technical discussion spontaneously.", ipa:"KAN-be-shray-bung", coll:"eine Kann-Beschreibung erfüllen", tip:"Kopf: die Beschreibung → die. Der Bindestrich hält *kann* als Zitat fest — so schreibt es der Referenzrahmen.", topic:"Exam", level:"C1" },
  { id:"fc9506", de:"Punktzahl", article:"die", plural:"die Punktzahlen", en:"score", vi:"số điểm", ex:"Ab einer Punktzahl von sechzig gilt der Test als bestanden.", exEn:"From a score of sixty the test counts as passed.", ipa:"PUNKT-tsaal", coll:"eine Punktzahl erreichen", tip:"Kopf: die Zahl → die. *bestehen* (to pass) ist stark: besteht, bestand, bestanden.", topic:"Exam", level:"B1" },
  { id:"fc9507", de:"Aussage", article:"die", plural:"die Aussagen", en:"statement", vi:"phát biểu", ex:"Diese Aussage würde ich abschwächen — belegen können wir sie nicht.", exEn:"I'd soften that statement — we can't back it up.", ipa:"AUS-zaa-ge", coll:"eine Aussage treffen", tip:"-e → die. Von *aussagen*. Vor Gericht heißt dasselbe Wort: die Zeugenaussage.", topic:"Speaking", level:"B2" },
  { id:"fc9508", de:"Abschwächung", article:"die", plural:"die Abschwächungen", en:"hedging, softening", vi:"cách nói giảm", ex:"Eine kleine Abschwächung wie *eher* nimmt dem Satz die Schärfe.", exEn:"A small hedge like „eher“ takes the edge off the sentence.", ipa:"AP-shve-khung", coll:"zur Abschwächung einsetzen", tip:"-ung → die. Die Werkzeuge dazu: eher, eigentlich, tendenziell, vielleicht, würde sagen. Im Deutschen Höflichkeit, nicht Unsicherheit.", topic:"Speaking", level:"C1" },
  { id:"fc9509", de:"Vermutung", article:"die", plural:"die Vermutungen", en:"assumption, conjecture", vi:"phỏng đoán", ex:"Das ist bisher nur eine Vermutung — ich prüfe sie heute Nachmittag.", exEn:"So far that's only an assumption — I'll check it this afternoon.", ipa:"fer-MUU-tung", coll:"eine Vermutung äußern", tip:"-ung → die. Verb: vermuten. Der grammatische Nachbar ist der Konjunktiv: *Es dürfte am Cache liegen.*", topic:"Speaking", level:"B2" },
  { id:"fc9510", de:"einschleichen (sich)", article:"—", plural:"—", en:"to creep in (an error)", vi:"lọt vào (lỗi)", ex:"Da hat sich ein Fehler eingeschlichen — kein Vorwurf, passiert jedem.", exEn:"An error has crept in there — no blame, happens to everyone.", ipa:"AYN-shlay-khen", coll:"es hat sich ein Fehler eingeschlichen", tip:"Reflexiv, trennbar, stark: schleicht sich ein, schlich sich ein, eingeschlichen. Die höflichste Art, im Review einen Bug zu melden.", topic:"Code Review", level:"C1" },
  { id:"fc9511", de:"Mitschrieb", article:"der", plural:"die Mitschriebe", en:"notes taken live", vi:"ghi chép tại chỗ", ex:"Mein Mitschrieb ist roh — das saubere Protokoll kommt heute Abend.", exEn:"My live notes are rough — the clean minutes come tonight.", ipa:"MIT-shreep", coll:"einen Mitschrieb anfertigen", tip:"Von *mitschreiben*. Regional; im Norden hört man eher *die Mitschrift*. Beides verständlich.", topic:"Writing", level:"C1" },
  { id:"fc9512", de:"unkritisch", article:"—", plural:"—", en:"uncritical; low-risk", vi:"không rủi ro", ex:"Der Patch ist unkritisch, den können wir auch freitags ausrollen.", exEn:"The patch is low-risk, we can ship that on a Friday.", ipa:"UN-krii-tish", coll:"als unkritisch einstufen", tip:"Zwei Register: eine Person ist *unkritisch* (naiv), eine Änderung ist *unkritisch* (ungefährlich). Der Kontext trennt.", topic:"DevOps", level:"B2" },
  { id:"fc9513", de:"Transkript", article:"das", plural:"die Transkripte", en:"transcript", vi:"bản ghi lời", ex:"Hör erst ohne Transkript, dann mit — sonst liest du nur.", exEn:"Listen without the transcript first, then with — otherwise you're just reading.", ipa:"trans-KRIPT", coll:"das Transkript mitlesen", tip:"Endbetont. Verwandt: *das Skript*, *die Transkription*. In diesem Projekt startet jedes Transkript versteckt.", topic:"Reading", level:"B2" },
  { id:"fc9514", de:"Redefluss", article:"der", plural:"—", en:"flow of speech, fluency", vi:"độ trôi chảy", ex:"Für den Redefluss ist es besser, einen Fehler stehen zu lassen als mitten im Satz zu korrigieren.", exEn:"For flow it's better to leave a mistake than to correct mid-sentence.", ipa:"REE-de-flus", coll:"den Redefluss halten", tip:"Kopf: der Fluss → der; Plural praktisch ungebräuchlich. In mündlichen Prüfungen ein eigenes Bewertungskriterium.", topic:"Speaking", level:"C1" },
  { id:"fc9515", de:"Stichwort", article:"das", plural:"die Stichwörter", en:"keyword, cue", vi:"từ khoá, ý chính", ex:"Schreib Stichwörter, keine ganzen Sätze — sonst liest du beim Sprechen ab.", exEn:"Write cues, not full sentences — otherwise you read aloud while speaking.", ipa:"SHTIKH-vort", coll:"sich Stichwörter notieren", tip:"Zwei Plurale mit Bedeutungsunterschied: *Stichwörter* (einzelne Wörter) und *Stichworte* (Anhaltspunkte). Beide gelten.", topic:"Speaking", level:"B2" },
  { id:"fc9516", de:"Kommunikation", article:"die", plural:"—", en:"communication", vi:"giao tiếp", ex:"An der Technik scheitert es selten, an der Kommunikation oft.", exEn:"It rarely fails on the technology, often on the communication.", ipa:"ko-mu-ni-ka-TSYOON", coll:"die interne Kommunikation", tip:"-tion → die, endbetont; Plural sehr selten. Im Incident heißt die Rolle dafür *Comms*.", topic:"Workplace", level:"B2" },
  { id:"fc9517", de:"wahrnehmen", article:"—", plural:"—", en:"to perceive; to attend (an appointment)", vi:"nhận thấy; tham dự", ex:"Den Termin kann ich wahrnehmen, ich verschiebe das Review.", exEn:"I can attend the appointment, I'll move the review.", ipa:"VAAR-nee-men", coll:"einen Termin wahrnehmen", tip:"Trennbar und stark: nehme … wahr, nahm … wahr, wahrgenommen. Zwei Sinne: sinnlich wahrnehmen und einen Termin wahrnehmen.", topic:"Workplace", level:"C1" },
  { id:"fc9518", de:"Abweichung", article:"die", plural:"die Abweichungen", en:"deviation, exception", vi:"sai lệch", ex:"Jede Abweichung von der Richtlinie braucht eine kurze Begründung im Ticket.", exEn:"Every deviation from the policy needs a brief justification in the ticket.", ipa:"AP-vay-khung", coll:"eine Abweichung begründen", tip:"-ung → die. Von *abweichen von* + Dativ. In der Statistik: die Standardabweichung.", topic:"Workplace", level:"C1" },
  { id:"fc9519", de:"Richtlinie", article:"die", plural:"die Richtlinien", en:"policy, guideline", vi:"quy định", ex:"Die Richtlinie verbietet Kundendaten auf dem Laptop, ohne Ausnahme.", exEn:"The policy forbids customer data on laptops, no exceptions.", ipa:"RIKHT-lii-nye", coll:"gegen eine Richtlinie verstoßen", tip:"-e → die. Deutlich verbindlicher als *die Empfehlung*: gegen eine Richtlinie *verstößt* man.", topic:"Security", level:"B2" },
  { id:"fc9520", de:"Ankündigung", article:"die", plural:"die Ankündigungen", en:"announcement", vi:"thông báo trước", ex:"Wartungsarbeiten laufen nur mit Ankündigung, mindestens eine Woche vorher.", exEn:"Maintenance only happens with an announcement, at least a week ahead.", ipa:"AN-kün-di-gung", coll:"eine Ankündigung verschicken", tip:"-ung → die. Von *ankündigen* — nicht *kündigen* (to quit / to give notice), das ist etwas ganz anderes.", topic:"Workplace", level:"B2" },
  { id:"fc9521", de:"gestattet", article:"—", plural:"—", en:"permitted", vi:"được phép", ex:"Der Zugriff von privaten Geräten ist nicht gestattet.", exEn:"Access from private devices is not permitted.", ipa:"ge-SHTA-tet", coll:"nicht gestattet sein", tip:"Partizip von *gestatten*. Behördendeutsch — im Aushang und in der Richtlinie steht *gestattet*, im Gespräch *erlaubt*.", topic:"Security", level:"C1" },
  { id:"fc9522", de:"Folie", article:"die", plural:"die Folien", en:"slide", vi:"slide", ex:"Fünf Folien reichen — den Rest erzählst du.", exEn:"Five slides is enough — you tell the rest.", ipa:"FOO-lye", coll:"eine Folie zeigen", tip:"-e → die. Gesprochen dreisilbig: FOO-li-e. Auch die Frischhaltefolie in der Küche.", topic:"Speaking", level:"B1" },
  { id:"fc9523", de:"gliedern", article:"—", plural:"—", en:"to structure, to divide up", vi:"chia bố cục", ex:"Ich gliedere den Vortrag in Problem, Lösung und offene Fragen.", exEn:"I'll structure the talk into problem, solution and open questions.", ipa:"GLEE-dern", coll:"einen Vortrag gliedern", tip:"Schwach: gliedert, gliederte, gegliedert. Nomen: die Gliederung — das Wort für „outline“ in jeder Prüfung.", topic:"Writing", level:"B2" },
  { id:"fc9524", de:"Zusammenarbeit", article:"die", plural:"—", en:"collaboration", vi:"sự hợp tác", ex:"Die Zusammenarbeit mit dem Platform-Team läuft seit dem Wechsel deutlich besser.", exEn:"Collaboration with the platform team has been much better since the change.", ipa:"tsu-ZA-men-ar-bayt", coll:"die Zusammenarbeit verbessern", tip:"Kopf: die Arbeit → die; Plural ungebräuchlich. *in Zusammenarbeit mit* ist die feste Formel in Berichten.", topic:"Workplace", level:"B2" },
  { id:"fc9525", de:"Rückfrage", article:"die", plural:"die Rückfragen", en:"follow-up question", vi:"câu hỏi lại", ex:"Bei Rückfragen melde dich gern jederzeit.", exEn:"If you have any follow-up questions, feel free to get in touch any time.", ipa:"RÜK-fraa-ge", coll:"bei Rückfragen melden", tip:"Kopf: die Frage → die. *Bei Rückfragen …* ist die Standard-Schlussformel geschäftlicher Mails.", topic:"Writing", level:"B2" },
  { id:"fc9526", de:"Anhang", article:"der", plural:"die Anhänge", en:"attachment; appendix", vi:"tệp đính kèm", ex:"Das Protokoll findest du im Anhang.", exEn:"You'll find the minutes in the attachment.", ipa:"AN-hang", coll:"im Anhang finden", tip:"Umlaut im Plural. Von *anhängen*. Gilt für die Mail wie für den Anhang eines Vertrags.", topic:"Writing", level:"B1" },
  { id:"fc9527", de:"Protokollant", article:"der", plural:"die Protokollanten", en:"minute-taker", vi:"người ghi biên bản", ex:"Wer ist heute Protokollant? Dann fangen wir an.", exEn:"Who's taking the minutes today? Then let's start.", ipa:"pro-to-ko-LANT", coll:"den Protokollanten bestimmen", tip:"N-Deklination: *den Protokollanten*, *dem Protokollanten* — im Akkusativ und Dativ mit *-en*. Weiblich: die Protokollantin.", topic:"Workplace", level:"C1" },

  /* ---- bewerbung/ · Anschreiben, Lebenslauf, Netzwerk ---- */
  { id:"fc9528", de:"Anschreiben", article:"das", plural:"die Anschreiben", en:"cover letter", vi:"thư xin việc", ex:"Das Anschreiben passt auf eine Seite — drei Absätze, kein Lebenslauf in Prosa.", exEn:"The cover letter fits one page — three paragraphs, not a CV in prose.", ipa:"AN-shray-ben", coll:"ein Anschreiben verfassen", tip:"Substantivierter Infinitiv → *das*, Plural = Singular. In Deutschland weiterhin erwartet, anders als im angelsächsischen Raum.", topic:"Career", level:"B2" },
  { id:"fc9529", de:"Wiederholungslogik", article:"die", plural:"—", en:"retry logic", vi:"logic thử lại", ex:"Ich habe die Wiederholungslogik eingebaut, die den Zahlungsdienst absichert.", exEn:"I built the retry logic that safeguards the payment service.", ipa:"VII-der-hoo-lungs-loo-gik", coll:"eine Wiederholungslogik einbauen", tip:"Kopf: die Logik → die. Im Team sagt man meist *der Retry* — im Anschreiben wirkt das deutsche Wort präziser.", topic:"Architecture", level:"C1" },
  { id:"fc9530", de:"einordnen", article:"—", plural:"—", en:"to put in context, to classify", vi:"định vị, xếp loại", ex:"Ordne die Zahl kurz ein: dreißig Prozent weniger Fehler als vorher.", exEn:"Put the figure in context briefly: thirty percent fewer errors than before.", ipa:"AYN-ord-nen", coll:"eine Zahl einordnen", tip:"Trennbar: ordne … ein. Im Anschreiben der Unterschied zwischen einer Zahl und einem Argument.", topic:"Career", level:"B2" },
  { id:"fc9531", de:"sich einarbeiten", article:"—", plural:"—", en:"to get up to speed", vi:"làm quen công việc", ex:"In eine neue Codebasis arbeite ich mich in etwa drei Wochen ein.", exEn:"I get up to speed on a new codebase in about three weeks.", ipa:"zikh AYN-ar-bay-ten", coll:"sich in ein Thema einarbeiten", tip:"Reflexiv und trennbar: arbeite mich … ein. *in* + Akkusativ. Nomen: die Einarbeitung(szeit).", topic:"Career", level:"B2" },
  { id:"fc9532", de:"Lebenslauf", article:"der", plural:"die Lebensläufe", en:"CV, résumé", vi:"sơ yếu lý lịch", ex:"Der Lebenslauf ist rückwärts chronologisch, die neueste Stelle steht oben.", exEn:"The CV is reverse chronological, the most recent role on top.", ipa:"LEE-bens-lauf", coll:"einen Lebenslauf aufsetzen", tip:"Umlaut im Plural. Wörtlich „Lauf des Lebens“. In Deutschland tabellarisch, ohne Foto-Pflicht seit dem AGG.", topic:"Career", level:"B2" },
  { id:"fc9533", de:"Berufserfahrung", article:"die", plural:"die Berufserfahrungen", en:"professional experience", vi:"kinh nghiệm làm việc", ex:"Mit vier Jahren Berufserfahrung bewerbe ich mich auf die Senior-Stelle.", exEn:"With four years of professional experience I'm applying for the senior role.", ipa:"be-RUUFS-er-faa-rung", coll:"Berufserfahrung mitbringen", tip:"Kopf: die Erfahrung → die. Fugen-s: Berufserfahrung, nicht Beruferfahrung. *mitbringen* ist das Bewerbungsverb schlechthin.", topic:"Career", level:"B2" },
  { id:"fc9534", de:"ablösen", article:"—", plural:"—", en:"to replace, to phase out", vi:"thay thế", ex:"Wir haben das alte System schrittweise abgelöst, ohne Ausfall.", exEn:"We phased out the old system step by step, with no downtime.", ipa:"AP-löö-zen", coll:"ein System ablösen", tip:"Trennbar: löse … ab. Auch: jemanden in der Schicht ablösen. Nomen: die Ablösung.", topic:"Architecture", level:"B2" },
  { id:"fc9535", de:"Gehaltsrahmen", article:"der", plural:"—", en:"salary range", vi:"khung lương", ex:"Können Sie mir den Gehaltsrahmen für die Stelle nennen?", exEn:"Could you tell me the salary range for the role?", ipa:"ge-HALTS-raa-men", coll:"den Gehaltsrahmen nennen", tip:"Kopf: der Rahmen → der. Die höflichste Art, früh nach Geld zu fragen — nach der Spanne, nicht nach der Zahl.", topic:"Career", level:"C1" },
  { id:"fc9536", de:"aufdringlich", article:"—", plural:"—", en:"pushy, intrusive", vi:"phiền phức", ex:"Einmal nachfassen ist nicht aufdringlich, dreimal in einer Woche schon.", exEn:"Following up once isn't pushy, three times in a week is.", ipa:"AUF-dring-likh", coll:"nicht aufdringlich wirken", tip:"Von *sich aufdrängen*. Beim Netzwerken die Grenze, die man auf Deutsch besser kennt als überschreitet.", topic:"Career", level:"C1" },
  { id:"fc9537", de:"abfangen", article:"—", plural:"—", en:"to catch, to absorb (a failure)", vi:"hứng lỗi", ex:"Den Ausfall des Zahlungsdienstes fangen wir mit einer Warteschlange ab.", exEn:"We absorb the payment service outage with a queue.", ipa:"AP-fang-en", coll:"einen Fehler abfangen", tip:"Trennbar und stark: fange … ab, fing … ab, abgefangen. Technisch: eine Ausnahme abfangen (catch).", topic:"Architecture", level:"B2" },
  { id:"fc9538", de:"in Kontakt bleiben", article:"—", plural:"—", en:"to stay in touch", vi:"giữ liên lạc", ex:"Lassen Sie uns in Kontakt bleiben — ich melde mich im Herbst noch einmal.", exEn:"Let's stay in touch — I'll get in touch again in the autumn.", ipa:"in kon-TAKT BLAY-ben", coll:"gern in Kontakt bleiben", tip:"Feste Wendung ohne Artikel. Der Standardabschluss jedes Netzwerkgesprächs — und beim Sie zwingend höflich formuliert.", topic:"Career", level:"B2" },
  { id:"fc9539", de:"eingruppieren", article:"—", plural:"—", en:"to classify into a pay grade", vi:"xếp bậc", ex:"Die Stelle wird in Gruppe elf eingruppiert, das ist tariflich festgelegt.", exEn:"The role is classified into grade eleven, that's set by collective agreement.", ipa:"AYN-gru-pee-ren", coll:"in eine Gruppe eingruppieren", tip:"Trennbar, aber ohne *ge-* im Partizip wegen *-ieren*: eingruppiert. Reines Tarif- und Behördenwort.", topic:"Career", level:"C1" },

  /* ---- foundations/ und plans/ ---- */
  { id:"fc9540", de:"Wortbildung", article:"die", plural:"die Wortbildungen", en:"word formation", vi:"cấu tạo từ", ex:"Wortbildung ist im Deutschen die halbe Miete: kennst du den Kopf, kennst du den Artikel.", exEn:"Word formation is half the battle in German: know the head, know the article.", ipa:"VORT-bil-dung", coll:"die Wortbildung durchschauen", tip:"-ung → die. *die halbe Miete* = most of the way there — eine sehr geläufige Redewendung.", topic:"Foundations", level:"B2" },
  { id:"fc9541", de:"Bestandteil", article:"der", plural:"die Bestandteile", en:"component, part", vi:"thành phần", ex:"Zerleg das Wort in seine Bestandteile, dann verliert es den Schrecken.", exEn:"Break the word into its components and it loses its terror.", ipa:"be-SHTANT-tayl", coll:"in Bestandteile zerlegen", tip:"Kopf: der Teil → der. Doppel-t an der Fuge: Bestand + Teil.", topic:"Foundations", level:"B2" },
  { id:"fc9542", de:"Gedächtnis", article:"das", plural:"die Gedächtnisse", en:"memory", vi:"trí nhớ", ex:"Das Gedächtnis behält, was wiederholt wird — nicht, was lange angeschaut wird.", exEn:"Memory keeps what gets repeated — not what gets stared at.", ipa:"ge-DEKHT-nis", coll:"im Gedächtnis behalten", tip:"Nomen auf *-nis* sind meist *das*, Plural mit Doppel-s. Nicht *die Erinnerung* — das ist die einzelne Erinnerung.", topic:"Foundations", level:"B2" },
  { id:"fc9543", de:"Fortschritt", article:"der", plural:"die Fortschritte", en:"progress", vi:"tiến bộ", ex:"Der Fortschritt zeigt sich nicht täglich, sondern im Rückblick über acht Wochen.", exEn:"Progress doesn't show daily but looking back over eight weeks.", ipa:"FORT-shrit", coll:"Fortschritte machen", tip:"Kopf: der Schritt → der. Meist im Plural: *Fortschritte machen*, nicht *Fortschritt machen*.", topic:"Foundations", level:"B1" },
  { id:"fc9544", de:"verbessern", article:"—", plural:"—", en:"to improve", vi:"cải thiện", ex:"Du verbesserst dein Hören schneller, wenn du dasselbe zweimal hörst statt zwei Dinge einmal.", exEn:"You improve your listening faster by hearing the same thing twice than two things once.", ipa:"fer-BE-sern", coll:"sich verbessern", tip:"Untrennbar, kein *ge-*: verbessert. Reflexiv *sich verbessern* = to get better; *jemanden verbessern* = to correct someone.", topic:"Foundations", level:"B1" },
  { id:"fc9545", de:"Wochenplan", article:"der", plural:"die Wochenpläne", en:"weekly plan", vi:"kế hoạch tuần", ex:"Der Wochenplan steht am Sonntag, nicht am Montagmorgen.", exEn:"The weekly plan is set on Sunday, not on Monday morning.", ipa:"VO-khen-plaan", coll:"den Wochenplan aufstellen", tip:"Umlaut im Plural. Kopf: der Plan → der.", topic:"Foundations", level:"B1" },
  { id:"fc9546", de:"Lernziel", article:"das", plural:"die Lernziele", en:"learning objective", vi:"mục tiêu học", ex:"Jedes Modul nennt sein Lernziel im ersten Absatz — lies den zuerst.", exEn:"Every module states its learning objective in the first paragraph — read that first.", ipa:"LERN-tseel", coll:"ein Lernziel formulieren", tip:"Kopf: das Ziel → das. Gute Lernziele beginnen mit *Ich kann …* — genau wie die Kann-Beschreibungen.", topic:"Foundations", level:"B1" },
  { id:"fc9547", de:"Ergebnis", article:"das", plural:"die Ergebnisse", en:"result, outcome", vi:"kết quả", ex:"Das Ergebnis zählt, aber der Weg dorthin gehört ins Protokoll.", exEn:"The result counts, but how you got there belongs in the minutes.", ipa:"er-GEEP-nis", coll:"zu einem Ergebnis kommen", tip:"Nomen auf *-nis* → meist *das*, Plural mit Doppel-s: Ergebnisse. Wie das Gedächtnis, das Hindernis.", topic:"Foundations", level:"B1" },

  /* ---- templates/ ---- */
  { id:"fc9548", de:"Unmut", article:"der", plural:"—", en:"displeasure, annoyance", vi:"sự bực bội", ex:"Ich verstehe den Unmut — der Termin war zugesagt, und wir haben ihn gerissen.", exEn:"I understand the annoyance — the date was promised and we missed it.", ipa:"UN-muut", coll:"Unmut äußern", tip:"Kein Plural. Formeller und kontrollierter als *der Ärger* — genau deshalb passt es in die Deeskalationsmail.", topic:"Writing", level:"C1" },
  { id:"fc9549", de:"erschöpfen (sich)", article:"—", plural:"—", en:"to be exhausted (a pool, a resource)", vi:"cạn kiệt", ex:"Der Verbindungspool erschöpft sich innerhalb von zwei Minuten.", exEn:"The connection pool exhausts itself within two minutes.", ipa:"er-SHÖP-fen", coll:"der Pool erschöpft sich", tip:"Untrennbar, kein *ge-*: erschöpft. Für Menschen genauso: *Ich bin erschöpft.* Nomen: die Erschöpfung.", topic:"DevOps", level:"C1" },
  { id:"fc9550", de:"Berechtigungsprüfung", article:"die", plural:"die Berechtigungsprüfungen", en:"authorization check", vi:"kiểm tra quyền", ex:"Die Berechtigungsprüfung fehlt auf dem zweiten Endpoint — das ist blockierend.", exEn:"The authorization check is missing on the second endpoint — that's blocking.", ipa:"be-REKH-ti-gungs-prüü-fung", coll:"eine Berechtigungsprüfung ergänzen", tip:"-ung → die (zweimal). Fugen-s. Unterscheide: die Authentifizierung (wer bist du) von der Berechtigungsprüfung (darfst du das).", topic:"Security", level:"C1" },
]);
